join exams e on e.id = q.exam_id
where e.slug = 'jeongchogi'
  and q.year = 2020
  and q.round = 3
  and q.subject = '정보시스템 구축관리'
  and q.number = 95
  and not exists (
    select 1 from choices c
    where c.question_id = q.id
      and c.number = 2
  );

